Import ListNotations.
Open Scope bv_scope.
Unset Lia Cache. Unset Nia Cache. Unset Nra Cache.
Ltac Zify.zify_convert_to_euclidean_division_equations_flag ::= constr:(false).

Ltac sok_in SOK :=
  store_ok_peel;
  first [ exact SOK
        | eapply store_ok_sub; [ | exact SOK | | ]; rewrite ?length_N_to_le_bytes, ?u_Z2bv by lia; cbn [Z.of_nat Pos.of_succ_nat Pos.succ]; lia ].

(* [comment removed for export] *)
Ltac ldcell F D a z :=
  stepLD F D (word_to_le_bytes 4 (Z_to_bv 64 z)) (Z_to_bv 64 z)
    ltac:(rdn_addr a; rdn_chain) ltac:(apply bytes_le_to_Z_4; unorm; lia);
  rewrite ?(v_lw_small z) by lia.

Definition PC_pixFlipTB : Z := 0x88bfc.

(* [comment removed for export] *)
Definition FRTB (m : word -> option byte) (s : Z) (ret : word) (regs : bvmap 5 word) : word -> option byte :=
  wbytes (wbytes (wbytes (wbytes (wbytes (wbytes (wbytes (wbytes (wbytes m
    (Z_to_bv 64 (s - 8)) (word_to_le_bytes 8 ret))
    (Z_to_bv 64 (s - 16)) (word_to_le_bytes 8 (getr regs 8)))
    (Z_to_bv 64 (s - 24)) (word_to_le_bytes 8 (getr regs 9)))
    (Z_to_bv 64 (s - 32)) (word_to_le_bytes 8 (getr regs 18)))
    (Z_to_bv 64 (s - 40)) (word_to_le_bytes 8 (getr regs 19)))
    (Z_to_bv 64 (s - 48)) (word_to_le_bytes 8 (getr regs 20)))
    (Z_to_bv 64 (s - 56)) (word_to_le_bytes 8 (getr regs 21)))
    (Z_to_bv 64 (s - 64)) (word_to_le_bytes 8 (getr regs 22)))
    (Z_to_bv 64 (s - 72)) (word_to_le_bytes 8 (getr regs 23)).
(* [comment removed for export] *)
Definition DIMTB (m : word -> option byte) (s : Z) (h d : Z) : word -> option byte :=
  wbytes (wbytes (wbytes (wbytes m
    (Z_to_bv 64 (s - 76)) (word_to_le_bytes 4 (Z_to_bv 64 0)))
    (Z_to_bv 64 (s - 80)) (word_to_le_bytes 4 (Z_to_bv 64 0)))
    (Z_to_bv 64 (s - 76)) (word_to_le_bytes 4 (Z_to_bv 64 h)))
    (Z_to_bv 64 (s - 80)) (word_to_le_bytes 4 (Z_to_bv 64 d)).
(* [comment removed for export] *)
Definition PCFTB (m : word -> option byte) (s pix : Z) (regs : bvmap 5 word) : word -> option byte :=
  wbytes (wbytes (wbytes (wbytes (wbytes m
    (Z_to_bv 64 (s - 88)) (word_to_le_bytes 8 (Z_to_bv 64 0x88c74)))
    (Z_to_bv 64 (s - 96)) (word_to_le_bytes 8 (Z_to_bv 64 pix)))
    (Z_to_bv 64 (s - 104)) (word_to_le_bytes 8 (Z_to_bv 64 pix)))
    (Z_to_bv 64 (s - 112)) (word_to_le_bytes 8 (getr regs 18)))
    (Z_to_bv 64 (s - 120)) (word_to_le_bytes 8 (getr regs 19)).
Definition MTB_A (m : word -> option byte) (s pix : Z) (v : pixv) (ret : word) (regs : bvmap 5 word) : word -> option byte :=
  PCFTB (DIMTB (FRTB m s ret regs) s (p_h v) (p_d v)) s pix regs.

Section RotTB.
Context {fx : FPState} {AL : AllocLayout} {CL : CallocLayout} {ASR : AllocSure}.
Context {PINS : @LeptPins AL LL16} {P16 : O23Pins}.
#[local] Notation "'u'" := bv_unsigned (only parsing).

Section Segs.
  Variable rom : word -> option byte.

  (* [comment removed for export] *)
  Lemma tb_A : forall regs m (s pix : Z) (v : pixv) (ret : word),
    (128 <= s)%Z -> (s < 2 ^ 64)%Z -> (1 <= pix)%Z -> PIXat m pix v -> (pix + 64 <= s - 128 \/ s <= pix)%Z -> p_d v = 1%Z ->
    store_ok SEGS m (Z_to_bv 64 (s - 128)) 128 = true ->
    getr regs 2 = Z_to_bv 64 s -> getr regs 1 = ret -> getr regs 10 = Z_to_bv 64 pix -> getr regs 11 = Z_to_bv 64 pix ->
    exists regs',
      msteps SEGS (mkst regs (0x88bfc : word) m rom) (mkst regs' (0xfa23c : word) (MTB_A m s pix v ret regs) rom)
      /\ getr regs' 2 = Z_to_bv 64 (s - 80) /\ getr regs' 1 = Z_to_bv 64 0x88c9c
      /\ getr regs' 10 = Z_to_bv 64 (p_wpl v) /\ getr regs' 11 = Z_to_bv 64 4
      /\ getr regs' 8 = Z_to_bv 64 pix /\ getr regs' 9 = Z_to_bv 64 (p_data v) /\ getr regs' 18 = Z_to_bv 64 pix
      /\ getr regs' 20 = Z_to_bv 64 (p_wpl v) /\ getr regs' 19 = getr regs 19
      /\ regs_agree (fun r => In r [1; 2; 8; 9; 10; 11; 12; 13; 14; 18; 19; 20]%list) regs regs'.
Proof.
