  Lemma tb_B1 : forall regs m (s h wpl data b : Z),
    (80 <= s)%Z -> (s < 2 ^ 64)%Z -> (2 <= h)%Z -> (1 <= wpl)%Z -> (4 * wpl * h < 2 ^ 31)%Z -> (0 <= data)%Z -> (data + 4 * wpl * h < 2 ^ 64)%Z ->
