  (* [comment removed for export] *)
  Lemma tb_B0 : forall regs m (s h b : Z),
    (80 <= s)%Z -> (s < 2 ^ 64)%Z -> (h = 1)%Z -> (1 <= b < 2 ^ 64)%Z ->
    rdn SEGS m (Z_to_bv 64 (s - 76)) 4 = Some (word_to_le_bytes 4 (Z_to_bv 64 h)) ->
    getr regs 2 = Z_to_bv 64 (s - 80) -> getr regs 10 = Z_to_bv 64 b ->
    exists regs',
      msteps SEGS (mkst regs (0x88c9c : word) m rom) (mkst regs' (0xfa374 : word) m rom)
      /\ getr regs' 2 = Z_to_bv 64 (s - 80) /\ getr regs' 1 = Z_to_bv 64 0x88d20
      /\ getr regs' 10 = Z_to_bv 64 b /\ getr regs' 18 = Z_to_bv 64 b
      /\ regs_agree (fun r => In r [1; 10; 11; 18]%list) regs regs'.
