  (* [comment removed for export] *)
  Lemma tb_L3n : forall regs m (lt lb wpl k : Z),
    (2 <= k < 2 ^ 31)%Z ->
    getr regs 9 = Z_to_bv 64 lt -> getr regs 20 = Z_to_bv 64 lb -> getr regs 21 = Z_to_bv 64 (4 * wpl) ->
    getr regs 22 = Z_to_bv 64 k -> getr regs 23 = Z_to_bv 64 (- (4 * wpl)) ->
    exists regs',
      msteps SEGS (mkst regs (0x88d08 : word) m rom) (mkst regs' (0x109cb0 : word) m rom)
      /\ getr regs' 1 = Z_to_bv 64 0x88ce8
      /\ getr regs' 9 = Z_to_bv 64 (lt + 4 * wpl) /\ getr regs' 20 = Z_to_bv 64 (lb - 4 * wpl) /\ getr regs' 22 = Z_to_bv 64 (k - 1)
      /\ getr regs' 10 = getr regs 18 /\ getr regs' 11 = Z_to_bv 64 (lt + 4 * wpl) /\ getr regs' 12 = getr regs 19
      /\ regs_agree (fun r => In r [1; 9; 10; 11; 12; 20; 22]%list) regs regs'.
