  (* [comment removed for export] *)
  Lemma tb_L3x : forall regs m (lt lb wpl : Z),
    getr regs 9 = Z_to_bv 64 lt -> getr regs 20 = Z_to_bv 64 lb -> getr regs 21 = Z_to_bv 64 (4 * wpl) ->
    getr regs 22 = Z_to_bv 64 1 -> getr regs 23 = Z_to_bv 64 (- (4 * wpl)) ->
    exists regs',
      msteps SEGS (mkst regs (0x88d08 : word) m rom) (mkst regs' (0xfa374 : word) m rom)
      /\ getr regs' 1 = Z_to_bv 64 0x88d20 /\ getr regs' 10 = getr regs 18
      /\ getr regs' 9 = Z_to_bv 64 (lt + 4 * wpl) /\ getr regs' 20 = Z_to_bv 64 (lb - 4 * wpl) /\ getr regs' 22 = Z_to_bv 64 0
      /\ regs_agree (fun r => In r [1; 9; 10; 20; 22]%list) regs regs'.
Proof.
